package com.circlenet.domain.moderation;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="abuse_reports") public class AbuseReportEntity{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="reporter_user_id",nullable=false) private Long reporterUserId; @Column(name="reported_user_id") private Long reportedUserId; @Column(name="entity_type",length=40) private String entityType; @Column(name="entity_id") private Long entityId; @Column(nullable=false,length=40) private String reason; @Column(length=2000) private String details; @Column(nullable=false,length=24) private String status="OPEN"; @Column(name="moderator_user_id") private Long moderatorUserId; @Column(name="moderator_notes",length=2000) private String moderatorNotes; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now();
 public Long getId(){return id;}public Long getReporterUserId(){return reporterUserId;}public void setReporterUserId(Long v){reporterUserId=v;}public Long getReportedUserId(){return reportedUserId;}public void setReportedUserId(Long v){reportedUserId=v;}public String getEntityType(){return entityType;}public void setEntityType(String v){entityType=v;}public Long getEntityId(){return entityId;}public void setEntityId(Long v){entityId=v;}public String getReason(){return reason;}public void setReason(String v){reason=v;}public String getDetails(){return details;}public void setDetails(String v){details=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Long getModeratorUserId(){return moderatorUserId;}public void setModeratorUserId(Long v){moderatorUserId=v;}public String getModeratorNotes(){return moderatorNotes;}public void setModeratorNotes(String v){moderatorNotes=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}
}
